def name_operands(region,address,operation):
 if region=='D3D' and address==0xEB10:
  operation=operation.replace('(#EB7C)','(@PreviewMultiplyState.ReturnTarget)')
  for (r,pc),label in LABELS.items():operation=operation.replace('#'+format(pc,'04X'),'@D3D.MultiplyPreviewCoordinate.'+label)
 return operation
